cd /home/exedev/shipshape-shakedown/.eval-scratch/R4-ctrl-flash/sim && node -e "
const bill = require('./watchbill.json');
const allRefs = Object.values(bill).flatMap(w => w.scenarios);
const fs = require('fs');
const path = require('path');

// Extract all scenario names from features
const featureFiles = allRefs.map(r => r.split(':')[0]).filter((v,i,a) => a.indexOf(v)===i);
const found = {};
featureFiles.forEach(f => {
  const content = fs.readFileSync(f, 'utf8');
  const matches = content.match(/Scenario: .+/g) || [];
  matches.forEach(s => {
    const name = s.replace(/^Scenario: /, '').trim();
    found[f + ':' + name] = true;
  });
});

const missing = allRefs.filter(r => !found[r]);
if (missing.length > 0) {
  console.log('MISSING scenarios:', missing);
} else {
  console.log('All', allRefs.length, 'scenarios found in feature files. OK.');
}

// Count per feature
featureFiles.forEach(f => {
  const refs = allRefs.filter(r => r.startsWith(f));
  console.log('  ' + f + ': ' + refs.length + ' refs');
});
"

